    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name readGrntFeeApproval
 * @description read Grnt Fee Approval 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readGrntFeeApproval = async function(row, colid) {
    if (colid === "STD_CD_APCT_ID") {
        const vROW = row; // ROW 임의지정
        const options = {
            id: "ULDINS21401",
            title: "수수료안내공문 신청 상세정보",
            type: "browserPopup",
            width: "580px",
            height: "490px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/etc/ULDINS21401.gfm", options);
    }
    /*
		else if (colid == "COM_NM") {
			if (row == 0) return;
			txb_param1.value = dts_PassList.NameValue(row,"ISUR_CD");// 발행기관코드
			txb_param2.value = dts_PassList.NameValue(row,"COM_NM"); // 발행기관명
			fn_GetPar = fn_GetParam;
			ins_popupOpen("","","ULDINS91600","발행기관 상세정보","1220","730");
		} */
};

/**
     * @method
     * @name btn_Search_onclick
     * @description 「조회」 클릭 이벤트
     * @returns {Promise<void>}
     * @hidden N
     */
scwin.btn_Search_onclick = async function() {
    await scwin.listGrntFeeApproval();
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};

/**
 * @method
